import{_ as o,o as a,c as s,a1 as d}from"./chunks/framework.DceXOx8u.js";const h=JSON.parse('{"title":"Notas de actualización: canales y plugins","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/actualizar-canales-plugins"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/actualizar-canales-plugins"}]]},"headers":[],"relativePath":"es/guide/actualizar-canales-plugins.md","filePath":"es/guide/actualizar-canales-plugins.md"}'),c={name:"es/guide/actualizar-canales-plugins.md"};function n(t,e,i,r,l,p){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="notas-de-actualizacion-canales-y-plugins" tabindex="-1">Notas de actualización: canales y plugins <a class="header-anchor" href="#notas-de-actualizacion-canales-y-plugins" aria-label="Permalink to &quot;Notas de actualización: canales y plugins&quot;">​</a></h1><p>Estos son los cambios desde la primera alpha (<code>@botmesh/core@2.0.0-alpha.2</code> y el resto en <code>0.2.0-alpha.0</code>) que pueden cambiar cómo se comporta un bot existente, en los paquetes de canales, stores y plugins. Cada uno dice qué cambió y qué hacer. La mayoría de los bots no necesitan ningún cambio.</p><h2 id="paquetes-publicos" tabindex="-1">Paquetes públicos <a class="header-anchor" href="#paquetes-publicos" aria-label="Permalink to &quot;Paquetes públicos&quot;">​</a></h2><h3 id="botmesh-baileys" tabindex="-1"><code>@botmesh/baileys</code> <a class="header-anchor" href="#botmesh-baileys" aria-label="Permalink to &quot;`@botmesh/baileys`&quot;">​</a></h3><p><strong><code>toJid()</code> lanza con una entrada que no puede convertir en JID.</strong> Devolvía <code>&#39;@s.whatsapp.net&#39;</code> para una entrada sin dígitos, y un texto inválido <code>…@g.us:&lt;usuario&gt;</code> para <code>{ groupId, userId }</code>. Las dos lanzan ahora un <code>TypeError</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ groupId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;120363000000000000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, userId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;573001112233&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// antes: texto inválido; ahora: TypeError</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ groupId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;120363000000000000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })                         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;120363000000000000@g.us&#39;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;573001112233&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;573001112233@s.whatsapp.net&#39;</span></span></code></pre></div><p>Un participante de un grupo no tiene JID propio: usa el JID del grupo para el chat y <code>toJid(userId)</code> para la persona.</p><p><strong>Las ediciones de texto llegan al bot.</strong> Un mensaje editado se descartaba. Ahora llega como mensaje con el texto nuevo y el <code>ref.id</code> <strong>original</strong>, como en Telegram. <code>isEditedMessage(ctx)</code> lo distingue. El dedupe del core deja pasar la edición y sigue descartando un reintento idéntico. Solo se entrega la edición de un mensaje que el proceso ha visto, enviado en el mismo chat por quien manda la edición: la que nombra el mensaje de otra persona, uno del propio bot o uno de otro chat se descarta, igual que la de un original que ya no está en la caché de mensajes del provider (p. ej. tras un reinicio). Para volver al comportamiento anterior:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaileysProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ session: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mi-bot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, editedMessages: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ignore&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><h3 id="botmesh-ai" tabindex="-1"><code>@botmesh/ai</code> <a class="header-anchor" href="#botmesh-ai" aria-label="Permalink to &quot;`@botmesh/ai`&quot;">​</a></h3><p><strong><code>provider: &#39;openai&#39;</code> con <code>baseUrl</code> envía <code>max_tokens</code>.</strong> Con cualquier <code>baseUrl</code> que no sea <code>api.openai.com</code> ni Azure OpenAI (<code>*.openai.azure.com</code>, <code>*.cognitiveservices.azure.com</code> o un endpoint de Azure AI Foundry <code>*.services.ai.azure.com</code> bajo <code>/openai</code>), el tope de tokens de salida va ahora en <code>max_tokens</code>, que es lo que esperan los servidores compatibles con OpenAI (vLLM, LM Studio, gateways). Si tu <code>baseUrl</code> es un proxy delante de OpenAI y usas un modelo o-series o gpt-5, vuelve a fijar el campo:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aiPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;openai&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, baseUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://mi-proxy.example/v1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maxTokensField: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;max_completion_tokens&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p><strong>Las opciones de memoria fallan pronto.</strong> Un <code>memory.maxFactLength</code>, <code>memory.maxFacts</code> o <code>memory.ttl</code> inválido lanza ahora un <code>RangeError</code> desde <code>aiPlugin()</code> en vez de fallar en <code>plug()</code> (o, con <code>maxFactLength</code>, descartar en silencio todos los hechos).</p><p><strong><code>onStreamEnd</code> tiene un contrato fijo.</strong> <code>GenerateInput.onStreamEnd(info)</code> (un <code>AIStreamEndInfo</code>: <code>stopReason</code>, más <code>usage</code> en Anthropic y Gemini) se llama exactamente una vez por llamada a <code>stream()</code>, tras el último fragmento y antes de que termine la iteración, y solo si el stream termina con normalidad: nunca si falla, se aborta o el consumidor sale antes con <code>break</code>. Una excepción lanzada por el callback hace fallar la iteración del consumidor. Todos los proveedores integrados y <code>MockAIProvider</code> lo cumplen, también la regla del aborto cuando el cliente ignora <code>signal</code> (un stream abortado no llama al callback y rechaza con el motivo del aborto); un <code>AIProvider</code> propio que llame a <code>onStreamEnd</code> también debería (comprueba <code>signal.aborted</code> antes de llamarlo).</p><p><strong>Entradas y datos congelados.</strong> <code>MockAIProvider</code> pasa a <code>@botmesh/ai/testing</code>, los helpers del plugin y los nombres de los tipos de los SDK a <code>@botmesh/ai/internal</code>, y los vocabularios, presets y textos exportados quedan congelados. Ver <a href="./migracion-estable#entradas-de-botmesh-ai">Migrar a la API estable</a>.</p><h3 id="botmesh-meta" tabindex="-1"><code>@botmesh/meta</code> <a class="header-anchor" href="#botmesh-meta" aria-label="Permalink to &quot;`@botmesh/meta`&quot;">​</a></h3><ul><li><strong>Los límites interactivos se comprueban antes de enviar.</strong> Un <code>buttons</code> o <code>card</code> sin botones, ids o títulos de botón repetidos (comparados tras el corte a 20 caracteres), una lista sin filas, con más de 10 filas o con ids de fila repetidos rechazan ahora con <code>UnsupportedContentError</code>. Graph también los rechazaba, pero con un error opaco tras la petición.</li><li><strong>Una respuesta interactiva que no es una pulsación</strong> (por ejemplo <code>call_permission_reply</code>) llega como mensaje <code>unknown</code> con el payload en <code>ctx.ref.native</code>, no como interacción <code>button</code> con datos vacíos. Un handler que dependía de eso debe leer el mensaje.</li><li>Las subidas de media tienen su propio timeout, <code>uploadTimeoutMs</code> (5 minutos por defecto).</li><li><strong>Nueva opción <code>lang</code></strong> para las etiquetas que <code>publishForm()</code> fija en un Flow (por defecto <code>&#39;en&#39;</code>): ponle el <code>BotConfig.lang</code> de tu bot. <code>publishForm(def, { lang })</code> la sobrescribe.</li><li><strong>Deprecados (se quitan en v3):</strong> <code>toProviderError</code> (usa <code>toGraphError</code> de <code>@botmesh/graph-core</code>), <code>GraphClient</code> (internos del transporte), los <code>verifyChallenge</code>/<code>verifySignature</code> reexportados (usa <code>provider.verifyChallenge(query)</code> y <code>provider.ingest()</code>, o impórtalos de <code>@botmesh/graph-core</code>) y <code>debug</code> (pasa un <code>logger</code>). <code>phoneNumberId</code> admite <code>string | number</code> en el tipo.</li></ul><h3 id="botmesh-telegram" tabindex="-1"><code>@botmesh/telegram</code> <a class="header-anchor" href="#botmesh-telegram" aria-label="Permalink to &quot;`@botmesh/telegram`&quot;">​</a></h3><ul><li>En modo webhook, <code>ingest()</code> tras <code>stop()</code> responde <code>503</code> y no emite nada (Telegram reenvía el Update tras el reinicio). Los hosts que vuelven a arrancar el provider no tienen que cambiar nada.</li><li>Las subidas de archivos tienen su propio timeout, <code>uploadTimeoutMs</code> (5 minutos por defecto).</li><li><strong>Las encuestas se envían no anónimas y sus votos llegan al bot.</strong> Cada <code>poll_answer</code> se convierte en un evento <code>&#39;poll&#39;</code> con la misma forma que en WhatsApp (<code>vote.ref</code>, <code>vote.senderId</code>, <code>vote.options</code> con <code>voters</code>). Los miembros del chat ven quién votó. Los canales no admiten votantes públicos: una encuesta a un canal se reintenta una vez como anónima (sin votos) y el canal se recuerda. Para mantener encuestas anónimas (sin recibir votos):</li></ul><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TelegramProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ token, anonymousPolls: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><ul><li><strong><code>pollTimeoutMs</code></strong> sustituye a <code>pollTimeout</code> (segundos, deprecado): <code>pollTimeout: 30</code> equivale a <code>pollTimeoutMs: 30_000</code>. <code>toProviderError</code> pasa a ser <code>toTelegramError</code> (el nombre antiguo es un alias deprecado), <code>debug</code> queda deprecado (pasa un <code>logger</code>) y los helpers de cable <code>parseUpdate</code>, <code>parsePollAnswer</code>, <code>toOutbound</code> y <code>MEDIA_UPLOAD</code> son <code>@experimental</code>.</li></ul><h3 id="botmesh-sqlite-store" tabindex="-1"><code>@botmesh/sqlite-store</code> <a class="header-anchor" href="#botmesh-sqlite-store" aria-label="Permalink to &quot;`@botmesh/sqlite-store`&quot;">​</a></h3><p><code>saveMessage</code> y <code>setCursor</code> lanzan <code>TypeError</code> con un id de mensaje, id de chat, clave o valor de cursor que lleve un surrogate UTF-16 suelto (antes SQLite lo guardaba como U+FFFD y dos ids podían compartir fila). Escapa o quita esos caracteres antes de guardarlos.</p><p><strong>Versionado del esquema.</strong> La base de datos guarda su layout en <code>PRAGMA user_version</code> (<code>SQLITE_SCHEMA_VERSION</code>, ahora <code>2</code>). Abrir un archivo escrito por una versión anterior (versión <code>0</code> o <code>1</code>) lo migra en el sitio y conserva todas las filas; no hay que hacer nada. La versión <code>2</code> incorpora a las migraciones versionadas las tablas del scheduler durable (<code>schedules</code>, <code>schedule_fences</code>) y la de durabilidad (<code>durable</code>): antes se creaban sobre la marcha la primera vez que se llamaba a <code>schedules()</code> o <code>durability()</code>, y ahora se crean al abrir el archivo. Un archivo escrito por una versión <strong>más nueva</strong> se rechaza con <code>SQLiteSchemaVersionError</code> (<code>code: &#39;SQLITE_SCHEMA_TOO_NEW&#39;</code>) y no se toca: no se admite volver atrás, así que haz una copia del archivo antes de actualizar si puedes necesitar revertir.</p><p><strong>Volver a la alpha anterior.</strong> La alpha anterior escribe y lee la versión de esquema <code>1</code>. En cuanto esta versión abre un archivo, este pasa a la versión <code>2</code> y la alpha anterior lo rechaza con <code>SQLITE_SCHEMA_TOO_NEW</code> en su siguiente arranque, aunque la app nunca llame a <code>schedules()</code> ni a <code>durability()</code>. Pasa lo mismo en un despliegue escalonado: un proceso que sigue en la alpha anterior y comparte el archivo falla al reiniciarse, así que para todos los procesos de la versión vieja antes de que el primero de la nueva abra el archivo. Para volver atrás, restaura la copia hecha antes de actualizar. La migración no cambia ninguna fila (solo añade tablas con <code>CREATE TABLE IF NOT EXISTS</code>), así que, si no tienes copia, puedes fijar a mano <code>PRAGMA user_version = 1</code> con la CLI <code>sqlite3</code> mientras ningún proceso tenga el archivo abierto, y la alpha anterior vuelve a abrirlo. El salto de versión existe para que las migraciones futuras puedan dar por hecho que esas tablas existen; sin él seguirían fuera de la versión.</p><p>Opciones nuevas: <code>busyTimeoutMs</code> (por defecto 5000, <code>PRAGMA busy_timeout</code>) y un <code>logger</code> que acepta cualquier <code>LoggerLike</code>. Las cadenas DDL exportadas <code>SCHEDULES_SCHEMA</code> y <code>DURABLE_SCHEMA</code> quedan deprecadas.</p><h3 id="botmesh-messenger-y-botmesh-instagram" tabindex="-1"><code>@botmesh/messenger</code> y <code>@botmesh/instagram</code> <a class="header-anchor" href="#botmesh-messenger-y-botmesh-instagram" aria-label="Permalink to &quot;`@botmesh/messenger` y `@botmesh/instagram`&quot;">​</a></h3><p>Los dos canales son públicos desde la beta (<code>1.0.0-beta</code>), así que su primera versión en npm ya trae la entrada congelada. Dentro del monorepo o de un fork, importar un nombre quitado deja de compilar:</p><table tabindex="0"><thead><tr><th>Quitado de la entrada principal</th><th>Usa en su lugar</th></tr></thead><tbody><tr><td><code>toProviderError</code></td><td><code>toMessengerError</code> / <code>toInstagramError</code></td></tr><tr><td>reexportaciones de <code>verifyChallenge</code>, <code>verifySignature</code></td><td><code>provider.verifyChallenge(query)</code> / <code>provider.ingest()</code>, o <code>@botmesh/graph-core</code></td></tr><tr><td><code>parseInbound</code>, <code>toOutbound</code>, <code>toOutboundMessages</code> (Messenger)</td><td><code>@botmesh/messenger/internal</code> (sin semver)</td></tr><tr><td><code>GraphClient</code>, <code>parseInbound</code>, <code>toOutbound</code> (Instagram)</td><td><code>@botmesh/instagram/internal</code> (sin semver)</td></tr><tr><td><code>GraphSendResponse</code> (Instagram)</td><td><code>InstagramSendResponse</code> (misma forma)</td></tr></tbody></table><p>La opción <code>debug</code> queda deprecada en los dos: pasa un <code>logger</code>. Más de 3 botones (o 10 filas de lista) en Messenger, o más de 13 quick replies en Instagram, rechazan con <code>UnsupportedContentError</code> en vez de cortarse.</p><h3 id="botmesh-evolution-botmesh-wppconnect-y-botmesh-wa-gateway-kit" tabindex="-1"><code>@botmesh/evolution</code>, <code>@botmesh/wppconnect</code> y <code>@botmesh/wa-gateway-kit</code> <a class="header-anchor" href="#botmesh-evolution-botmesh-wppconnect-y-botmesh-wa-gateway-kit" aria-label="Permalink to &quot;`@botmesh/evolution`, `@botmesh/wppconnect` y `@botmesh/wa-gateway-kit`&quot;">​</a></h3><p>Nuevos en npm en la beta (antes eran privados). Si los usabas desde el monorepo:</p><ul><li>Los parsers de webhooks, los mapeadores de salida y los tokens de media (<code>parseWebhook</code>, <code>parseMessage</code>, <code>toOutbound</code>, <code>numberedMenu</code>, <code>keyFromRef</code>, <code>target</code>, <code>jidOf</code>…) y los helpers JWT de Evolution (<code>verifyHs256Jwt</code>, <code>signHs256Jwt</code>) pasaron a <code>@botmesh/evolution/internal</code> y <code>@botmesh/wppconnect/internal</code>, sin garantía semver.</li><li>Los providers ya no reexportan <code>WaIdentityStore</code> ni <code>normalizeJid</code>: impórtalos de <code>@botmesh/wa-gateway-kit</code>. <code>IdentityPersistence</code> y <code>RestHttpOptions</code> siguen en la entrada principal de los providers.</li><li>Se quitó la opción <code>debug</code>: pasa un <code>logger</code> (<code>pino({ level: &#39;debug&#39; })</code>).</li><li>Las opciones inválidas lanzan <code>TypeError</code> (antes un <code>Error</code> genérico; los mensajes no cambian). Además, <code>baseUrl</code> ya no admite credenciales (<code>user:pass@</code>), query string ni fragmento, <code>identityCacheSize</code> debe ser un entero positivo (o <code>Infinity</code>) y <code>http.timeoutMs</code> / <code>http.maxBytes</code> se validan al construir el provider, no en la primera petición.</li><li>Solo una URL <code>http(s)</code> se entrega al gateway para que la descargue. <code>{ url }</code> es siempre un enlace, como en Meta y Telegram: admite <code>http(s)</code> o un <code>data:</code> URI en base64 (que va inline), y una ruta local o una URL <code>file:</code> ahí rechaza con <code>UnsupportedContentError</code> en vez de leerse (antes se pasaba tal cual y el gateway intentaba abrir esa ruta en su propio host). Envía un archivo local como <code>{ path }</code> o como string con la ruta; el bot lo lee y lo manda en base64.</li></ul><h2 id="plugins-que-pasan-a-npm" tabindex="-1">Plugins que pasan a npm <a class="header-anchor" href="#plugins-que-pasan-a-npm" aria-label="Permalink to &quot;Plugins que pasan a npm&quot;">​</a></h2><p><code>@botmesh/rag</code>, <code>@botmesh/voice</code>, <code>@botmesh/nlu</code>, <code>@botmesh/dialogflow</code>, <code>@botmesh/chatwoot</code>, <code>@botmesh/tickets</code> y <code>@botmesh/moderation</code> se publican en npm desde la beta (<code>1.0.0-beta</code>). El código que los usaba desde el monorepo (<code>workspace:*</code>) necesita estos cambios:</p><ul><li><strong>Helpers movidos a una entrada <code>/internal</code></strong> (sin semver; una aplicación rara vez los necesita): <code>@botmesh/rag/internal</code> (<code>splitMarkdownSections</code>, <code>resolveChunkOptions</code>, <code>cosine</code>, <code>hashText</code>, <code>tokenize</code>, <code>resolveEmbedder</code>, <code>createPdfParser</code>), <code>@botmesh/voice/internal</code> (<code>trimPunctuation</code>, <code>resolveStt</code>, <code>resolveTts</code>, <code>OPENAI_TTS_MIMETYPES</code>, <code>elevenLabsMimetype</code>, <code>estimateOggDurationSec</code>, <code>estimateDurationSec</code>, <code>sniffMimetype</code>), <code>@botmesh/dialogflow/internal</code> (<code>normalizeEsResult</code>, <code>normalizeCxResult</code>, <code>toSessionId</code>, <code>parseCredentials</code>, <code>createServiceAccountJwt</code>, <code>DIALOGFLOW_SCOPE</code>, <code>DEFAULT_TOKEN_URI</code>), <code>@botmesh/chatwoot/internal</code> (<code>ChatwootMapping</code>, <code>verifyWebhook</code>, <code>inboundText</code>, <code>outboundText</code>), <code>@botmesh/tickets/internal</code> (<code>renderTemplate</code>, <code>localClock</code>) y <code>@botmesh/moderation/internal</code> (<code>findLinks</code>, <code>findInviteLinks</code>, <code>compileTerms</code>, <code>foldText</code>).</li><li><strong><code>@botmesh/dialogflow</code>:</strong> <code>dialogflowPlugin</code> es el nombre canónico y <code>dialogflowContext</code> un alias obsoleto. <code>languageCode</code> vale por defecto <code>&#39;en&#39;</code> (antes <code>&#39;es&#39;</code>): ponle el idioma de tu agente. En grupos, <code>sessionScope</code> vale por defecto <code>&#39;participant&#39;</code> (una sesión de Dialogflow por miembro, como las conversaciones); usa <code>sessionScope: &#39;chat&#39;</code> para mantener una sesión por grupo. Las opciones mal escritas (<code>minConfidence: 80</code>, un <code>fulfillment</code> desconocido…) lanzan ahora <code>DialogflowError</code> (<code>INVALID_CONFIG</code>) en <code>bot.plug()</code>, y los textos de más de 256 caracteres ya no se envían (<code>maxTextLength</code>).</li><li><strong>Datos congelados:</strong> <code>DEFAULT_VOICE_LIMITS</code>, <code>SUPPORTED_EXTENSIONS</code> (rag), <code>TICKET_PRIORITIES</code> y <code>TICKET_STATUSES</code> ya no se pueden mutar; cópialos antes.</li><li><strong><code>@botmesh/chatwoot</code>:</strong> se rechaza una firma de webhook sin <code>x-chatwoot-timestamp</code> (no caducaba, así que una petición capturada se podía repetir). Activa <code>webhookAllowUntimedSignature: true</code> solo para un emisor que no pueda añadir el timestamp.</li><li><strong><code>@botmesh/tickets</code>:</strong> <code>TicketKeyValue</code> tiene un <code>setIf</code> opcional. Un almacenamiento propio que lo implemente pasa el desk a modo compartido (seguro con réplicas).</li></ul><h2 id="paquetes-que-eran-privados" tabindex="-1">Paquetes que eran privados <a class="header-anchor" href="#paquetes-que-eran-privados" aria-label="Permalink to &quot;Paquetes que eran privados&quot;">​</a></h2><p>Estas notas importan al código que usaba los paquetes desde el monorepo o un fork antes de la beta. <code>@botmesh/discord</code>, <code>@botmesh/email</code> y <code>@botmesh/flow-schema</code> están en npm desde la beta; <code>@botmesh/tiktok</code> y los paquetes de producto siguen siendo privados.</p><ul><li><strong><code>@botmesh/discord</code>:</strong> <code>ctx.interaction.id</code> (<code>interactionId</code>) es el id de la interacción a secas; el token se queda en el provider, y la forma alfa <code>&quot;&lt;id&gt;:&lt;token&gt;&quot;</code> de <code>acknowledgeInteraction()</code> se quitó antes de la primera publicación (solo se conocen los ids que recibió el provider). Las interacciones que el bot no confirma en <code>autoAcknowledgeMs</code> (2 s; el alias alfa <code>autoAckMs</code> se quitó) se difieren por él; pon <code>autoAcknowledgeMs: false</code> para seguir haciéndolo tú. Los mensajes enviados llevan <code>allowed_mentions: { parse: [&#39;users&#39;] }</code> si no indican otro (<code>allowedMentions</code> lo cambia), así que <code>@everyone</code>, <code>@here</code> y las menciones de rol ya no notifican por defecto. Las ediciones de mensajes (<code>MESSAGE_UPDATE</code>) llegan ahora como mensajes con el <code>ref.id</code> original (<code>isEditedMessage(ctx)</code>; <code>editedMessages: &#39;ignore&#39;</code> las descarta).</li><li><strong>Mapeadores de errores renombrados</strong> (los nombres antiguos son alias deprecados): <code>toTikTokError</code>, <code>toEmailError</code>. <code>toDiscordError</code> no tiene alias: <code>toProviderError</code> se quitó de <code>@botmesh/discord</code> antes de su primera publicación.</li><li><strong>Stores de producto:</strong> <code>InboxStore.erase</code>, <code>ContactStore.erase</code> y <code>DeploymentStore.prune</code> son métodos nuevos obligatorios, y <code>DeploymentStore.list</code> / <code>InboxStore.listNotes</code> aceptan un cursor <code>after</code>. Un store propio debe añadirlos (las suites de conformidad compartidas de <code>test-utils/</code> los comprueban). <code>attachInbox()</code> sin <code>tenantId</code> guarda ahora las conversaciones en el tenant del propio bot en vez de <code>&#39;local&#39;</code>.</li><li><strong><code>@botmesh/flow-schema</code>:</strong> <code>publishFlow()</code> acepta cualquier registro con un <code>publish()</code> compatible (un <code>DeploymentRegistry</code> encaja) y ya no depende de <code>@botmesh/deployments</code> en tiempo de ejecución.</li></ul>',39)])])}const m=o(c,[["render",n]]);export{h as __pageData,m as default};
